<script setup>
import {PuzzleIcon,SendIcon} from '@lucide/vue'


import PageHeader from "../../shared/components/PageHeader.vue"
import {ref, onMounted, computed} from 'vue'
import HelpTip from '../../shared/components/HelpTip.vue'
const steps=ref([]),drivers=ref([]),tab=ref('steps')
onMounted(async()=>{[steps.value,drivers.value]=await Promise.all([fetch('api/steps').then(r=>r.json()),fetch('api/deploy/drivers').then(r=>r.json())])})
const kindText=k=>({source:'源码',build:'构建',package:'制品',deploy:'部署'}[k]||k)
const buildSteps=computed(()=>steps.value.filter(v=>v.kind!=='deploy'))



import {Accordion,AccordionItem,AccordionTrigger,AccordionContent,Tabs,TabsContent,TabsList,TabsTrigger} from '../../shared/shadcn-ui.js'
</script>
<template><div><PageHeader title="插件中心" help="构建步骤负责生成制品；部署驱动根据应用环境解析目标并执行发布。"><template #navigation><Tabs class="section-tabs" :model-value="String(tab)" @update:model-value="(value=>tab=value)($event)"><div class="flex min-w-0 items-center gap-2"><TabsList variant="line" class="h-auto! min-h-9 max-w-full flex-wrap justify-start gap-x-3 gap-y-1 [&>[data-slot=tabs-trigger]]:h-9 [&>[data-slot=tabs-trigger]]:flex-none"><TabsTrigger :value="&quot;steps&quot;">{{'构建步骤（'+buildSteps.length+'）'}}</TabsTrigger><TabsTrigger :value="&quot;drivers&quot;">{{'部署驱动（'+drivers.length+'）'}}</TabsTrigger></TabsList></div><TabsContent :value="&quot;steps&quot;" force-mount v-show="!(String(tab)!==&quot;steps&quot;)" class="min-w-0"></TabsContent><TabsContent :value="&quot;drivers&quot;" force-mount v-show="!(String(tab)!==&quot;drivers&quot;)" class="min-w-0"></TabsContent></Tabs></template></PageHeader><div v-if="tab==='steps'" class="grid"><article v-for="v in buildSteps" :key="v.id"><header><PuzzleIcon class="size-5 shrink-0 text-muted-foreground"/><div><b>{{v.name}}</b><code>{{v.id}}</code></div><em>{{kindText(v.kind)}}</em></header><p>{{v.description||'无说明'}}</p><dl><div><dt>API</dt><dd>{{v.api_version}}</dd></div><div><dt>输入制品</dt><dd>{{v.accepts?.join(', ')||'—'}}</dd></div><div><dt>输出制品</dt><dd>{{v.produces||'—'}}</dd></div><div><dt>参数</dt><dd>{{v.params?.length||0}} 个</dd></div></dl></article></div><div v-else class="grid"><article v-for="v in drivers" :key="v.id"><header><SendIcon class="size-5 shrink-0 text-muted-foreground"/><div><b>{{v.name}}</b><code>{{v.id}}</code></div><em>部署</em></header><p>接受 {{v.accepts.join(', ')}} 制品</p><dl><div><dt>API</dt><dd>{{v.api_version}}</dd></div><div><dt>能力</dt><dd>{{v.capabilities.join(' · ')}}</dd></div><div><dt>扩展参数</dt><dd>{{v.params?.length||0}} 个</dd></div></dl></article></div><Accordion type="single" collapsible class="mt-4"><AccordionItem value="contract"><AccordionTrigger>通用插件契约</AccordionTrigger><AccordionContent><span class="text-sm text-muted-foreground">构建步骤声明 <code>kind / produces / accepts</code>；部署驱动声明 <code>accepts / capabilities / params</code>，由发布单注入环境和主机快照。两者不能混在同一条构建流水线中。</span></AccordionContent></AccordionItem></Accordion></div></template>
<style scoped>.head{display:flex;align-items:center;gap:7px}.head h2{font-size:1.25rem}nav{display:flex;border-bottom:1px solid var(--border);margin:10px 0 18px}nav a{padding:8px 14px;color:var(--muted-foreground);cursor:pointer;border-bottom:2px solid transparent}nav a.active{color:var(--brand);border-color:var(--brand)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:10px}.grid article{background:var(--panel);border:1px solid var(--border);border-radius:var(--radius);padding:14px}.grid header{display:flex;align-items:center;gap:9px}.grid header>span{font-size:1.25rem}.grid header div{display:flex;flex-direction:column}.grid header code{font-size:.75rem;color:var(--dim)}.grid header em{font-style:normal;margin-left:auto;font-size:.75rem;background:var(--panel2);padding:2px 7px;border-radius:var(--radius)}.grid p{color:var(--muted-foreground);font-size:.75rem;min-height:34px;margin:10px 0}.grid dl div{display:grid;grid-template-columns:75px 1fr;font-size:.75rem;padding:3px 0}.grid dt{color:var(--dim)}.grid dd{word-break:break-all}.contract{display:flex;flex-direction:column;background:var(--panel2);padding:12px;border-radius:var(--radius);margin-top:16px}.contract span{font-size:.75rem;color:var(--muted-foreground)}</style>

<style scoped>.grid article{min-width:0}.grid header div{min-width:0;overflow-wrap:anywhere}.grid header em{flex-shrink:0}</style>
